{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "NSH Gallery UI (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "NSH Gallery UI default theme: graphite dark and paper light surfaces with citrus lime (`#c6ef6a`) brand fill, continuous squircle corners, spring motion physics, and layered surface finishes.",
        "elevation": "Tactile layered elevation: inner top-edge highlights (`inset`), 1px hairline borders, contact + cast drop shadows (`card`, `menu`, `modal`, `inverse`), and translucent frosted glass (`glass` with 80% popover alpha).",
        "dos": [
          "Preserve the citrus accent (`primary` / `primary-foreground`) for primary actions, active runs, and focus highlights.",
          "Use `inset` wells inside cards and `raised` surfaces for controls sitting on cards, paired with continuous squircle corners (`shape.curve: \"continuous\"`).",
          "Apply tactile spring press feedback (`state.press-scale: 0.97`, `motion.default` / `motion.slow`)."
        ],
        "donts": [
          "Do not flatten shadows or remove inner highlights on `card`, `raised`, `inset`, or `pill` finishes.",
          "Do not merge distinct semantic finishes (`light` vs `accent`, `thumb` vs `raised`, `knob` vs `handle`)."
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Semantic typography roles referencing tier-specific font.size and font.line-height.",
    "caption": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.caption}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.label}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.label}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Control labels, form labels, and interactive triggers."
    },
    "title": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.title}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.title}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Card and section headings."
    },
    "headline": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.headline}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.headline}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Page-level headings."
    },
    "display": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.display}",
        "fontWeight": 600,
        "lineHeight": "{font.line-height.display}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Large display numerals and hero headings."
    }
  },
  "dimension": {
    "$type": "dimension",
    "$description": "Desktop pointer layout density, control geometry, and icon sizes.",
    "shape": {
      "$type": "dimension",
      "$description": "Semantic corner radius roles by layer, referencing base dimension.radius.* tokens.",
      "control": {
        "$value": "{dimension.radius.control}",
        "$description": "Corner radius for in-page elements: buttons, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": "{dimension.radius.container}",
        "$description": "Corner radius for containers and overlays: cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": "{dimension.radius.modal}",
        "$description": "Corner radius for modal surfaces: dialogs, sheets, and drawers."
      }
    },
    "stroke": {
      "$description": "Border stroke widths.",
      "hairline": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Hairline width for dividers, container edges (cards, drawers, overlays) and outlined variants."
      },
      "control": {
        "$value": {
          "value": 1,
          "unit": "px"
        },
        "$description": "Interactive control border width."
      }
    },
    "focus": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "style": "halo"
        }
      },
      "$description": "Focus ring geometry and style enum.",
      "width": {
        "$value": {
          "value": 3,
          "unit": "px"
        },
        "$description": "Focus ring stroke width."
      },
      "offset": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Focus ring outward offset from control bounds."
      }
    },
    "control": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "selection": "pill",
          "field": "box",
          "choice": "well",
          "track": "sunk",
          "handle": "circle",
          "group": "track"
        }
      },
      "$description": "Control dimensions: the six behaviour-named axes a theme decides for its controls (selection, field, choice, track, handle, group). Themes override only the axes that differ."
    },
    "radius": {
      "$type": "dimension",
      "$description": "Corner radius roles by layer (8px control, 12px container, 14px modal) referenced by semantic shape roles.",
      "control": {
        "$value": {
          "value": 8,
          "unit": "px"
        },
        "$description": "Corner radius for in-page controls, fields, rows, chips, badges, wells, color areas, and kbd."
      },
      "container": {
        "$value": {
          "value": 12,
          "unit": "px"
        },
        "$description": "Corner radius for cards, menus, popovers, tooltips, list panels, toasts, and frames."
      },
      "modal": {
        "$value": {
          "value": 14,
          "unit": "px"
        },
        "$description": "Corner radius for dialogs, sheets, and drawers."
      }
    },
    "size": {
      "$description": "Ergonomic sizing scales for pointer input.",
      "hit": {
        "$value": {
          "value": 0,
          "unit": "px"
        },
        "$description": "Minimum hit target size (0 disables padding expansion)."
      },
      "density": {
        "$description": "Page-level padding and gap.",
        "pad": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 12,
            "unit": "px"
          }
        }
      },
      "item": {
        "$description": "A list's rows in a popup or a palette: inset, the container's edge to the row's fill; pad, the fill's edge to its text. shadcn's select and menus: 4 (SelectContent p-1) and 8 (SelectItem pl-2).",
        "inset": {
          "$value": {
            "value": 4,
            "unit": "px"
          }
        },
        "pad": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        }
      },
      "control": {
        "$extensions": {
          "dev.aning.shadcn-nsh": {
            "switch": "small"
          }
        },
        "$description": "Control internal spacing and switch size tier.",
        "padding": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        },
        "gap": {
          "$value": {
            "value": 8,
            "unit": "px"
          }
        },
        "dot": {
          "$value": {
            "value": 6,
            "unit": "px"
          }
        }
      },
      "height": {
        "$description": "Standard control heights (sm, md, lg).",
        "sm": {
          "$value": {
            "value": 24,
            "unit": "px"
          }
        },
        "md": {
          "$value": {
            "value": 28,
            "unit": "px"
          }
        },
        "lg": {
          "$value": {
            "value": 32,
            "unit": "px"
          }
        }
      }
    },
    "icon": {
      "$description": "Standard icon dimensions (sm, md, lg).",
      "sm": {
        "$value": {
          "value": 12,
          "unit": "px"
        }
      },
      "md": {
        "$value": {
          "value": 16,
          "unit": "px"
        }
      },
      "lg": {
        "$value": {
          "value": 20,
          "unit": "px"
        }
      }
    }
  },
  "shape": {
    "$description": "Non-dimensional corner curve and button capsule flag.",
    "$extensions": {
      "dev.aning.shadcn-nsh": {
        "curve": "continuous",
        "corners": {
          "button": "radius"
        }
      }
    }
  },
  "state": {
    "$type": "number",
    "$extensions": {
      "dev.aning.shadcn-nsh": {
        "ripple": false
      }
    },
    "$description": "Interaction state opacities, press scale, and ripple switch.",
    "press-scale": {
      "$value": 0.97,
      "$description": "Scale factor applied while a pressable control is pressed."
    },
    "overlay": {
      "$description": "State-layer ink opacities for hover, focus, pressed, and dragged states.",
      "hover": {
        "$value": 0
      },
      "focus": {
        "$value": 0
      },
      "pressed": {
        "$value": 0
      },
      "dragged": {
        "$value": 0
      }
    },
    "pressed-opacity": {
      "$value": 0.7,
      "$description": "Content opacity when pressed."
    },
    "rest-opacity": {
      "$value": 0.5,
      "$description": "Opacity a passive indicator sits at rest (a scrollbar's thumb), before the pointer is on it."
    },
    "disabled": {
      "$description": "Disabled content opacity multiplier and whether containers switch to a dedicated disabled fill.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "fill": false
        }
      },
      "content": {
        "$value": 0.5
      }
    }
  },
  "transition": {
    "$type": "transition",
    "$description": "Named CSS/NSH transition presets.",
    "enter": {
      "$value": {
        "duration": {
          "value": 420,
          "unit": "ms"
        },
        "delay": {
          "value": 0,
          "unit": "ms"
        },
        "timingFunction": "{cubicBezier.out-cubic}"
      },
      "$description": "Default surface entrance transition."
    }
  },
  "motion": {
    "$description": "Interactive spring and timing physics roles: fast, default, slow, and the state fade.",
    "fast": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "spring": {
            "stiffness": 1218,
            "damping": 70
          }
        }
      },
      "$description": "Quickest response: small control toggles and thumbs."
    },
    "default": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "spring": {
            "stiffness": 520,
            "damping": 34
          }
        }
      },
      "$description": "Everyday feedback: presses, releases and modest movement."
    },
    "slow": {
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "spring": {
            "stiffness": 320,
            "damping": 30
          }
        }
      },
      "$description": "Slowest: large surfaces and long-travel layout movement."
    },
    "state": {
      "$description": "State fade: how fast hover, press and choice states come and go (upstream nsh-gallery-ui's hover wash, 120 ms ease-out).",
      "timing": {
        "$type": "transition",
        "$value": {
          "duration": {
            "value": 120,
            "unit": "ms"
          },
          "delay": {
            "value": 0,
            "unit": "ms"
          },
          "timingFunction": "{cubicBezier.out-cubic}"
        },
        "$description": "120 ms out-cubic: upstream nsh-gallery-ui's hover wash (120 ms ease-out)."
      }
    }
  },
  "finish": {
    "$description": "The neutral fields of every finish role, written once: a flat surface states no gradient, an opaque one no backdrop blur and no material, a layer no height of its own, a press that keeps the resting colours states no swap, and a top or bottom edge with no colour of its own takes the role's border color. A theme that states one writes the token (its own finishes.shared, or an appearance's) and it wins; the extension only says what the neutral is where no token states it, so a compiled finish carries every field in every theme.",
    "card": {
      "$description": "A surface that holds content: a card, a section.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.card}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.md}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      }
    },
    "inset": {
      "$description": "A well cut into a surface: an inset, a field, a track, a groove.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.inset}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      }
    },
    "channel": {
      "$description": "The channel a group of choices sits in: a segmented control's track.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.inset}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.inset}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      }
    },
    "raised": {
      "$description": "A control on a surface: a button, a chip, a pill.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.raised}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.edge.surface}",
          "{shadow.sm}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "border-top-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "border-bottom-color": {
        "$type": "color",
        "$value": "{color.border}"
      }
    },
    "plate": {
      "$description": "A labelled block chosen inside a well: the selected tab, a segmented control's thumb.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.card}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.edge.surface}",
          "{shadow.sm}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      },
      "border-top-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "border-bottom-color": {
        "$type": "color",
        "$value": "{color.border}"
      }
    },
    "overlay": {
      "$description": "A panel floating over the page: a menu, a toast.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.popover}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.lg}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      }
    },
    "modal": {
      "$description": "A surface the page waits for: a dialog, a sheet.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.card}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.xl}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.foreground}"
      }
    },
    "inverse": {
      "$description": "The page's inverse: an inverse surface, a tooltip.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "none",
          "border-bottom-color": "none",
          "border-top-color": "none",
          "elevation": null,
          "gradient": "none",
          "material": "none",
          "pressed-background": "none",
          "pressed-foreground": "none"
        }
      },
      "background": {
        "$type": "color",
        "$value": "{color.inverse}"
      },
      "border-color": {
        "$type": "color",
        "$value": "{color.border}"
      },
      "shadow": {
        "$type": "shadow",
        "$value": [
          "{shadow.lg}"
        ]
      },
      "foreground": {
        "$type": "color",
        "$value": "{color.inverse-foreground}"
      }
    },
    "glass": {
      "$description": "A translucent surface: what is behind it shows through.",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "backdropFilter": "blur(20px)",
          "border-bottom-color": "none",
